const starterHtmlS2=`<!doctype html>
<html lang="ca">
  <head>
    <meta charset="utf-8">
    <title>ByteFest</title>
  </head>
  <body>
    <!-- Presentació principal -->
    <h1>ByteFest</h1>
    <p>Una trobada per descobrir tecnologia creativa.</p>

    <!-- Primer apartat -->
    <h2>Què hi trobaràs</h2>
    <p>Podràs provar <strong>arcade i robòtica</strong>.</p>
    <h3>Taller destacat</h3>
    <p>Construirem un joc <em>pas a pas</em>.</p>

    <h2>Horaris</h2>
    <p>Dissabte de 10 a 13 h.</p>
  </body>
</html>`;
function activateHtmlLabS2(){const editor=document.querySelector('#htmlEditorS2'),status=document.querySelector('#labStatusS2');let preview=document.querySelector('#htmlPreviewS2');if(!editor||!preview)return;const render=()=>{const next=preview.cloneNode(false);next.srcdoc=editor.value;preview.replaceWith(next);preview=next;status.textContent=`Previsualització actualitzada · ${new Date().toLocaleTimeString('ca-ES',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`};editor.value=starterHtmlS2;render();document.querySelector('#runHtmlS2').addEventListener('click',render);document.querySelector('#resetHtmlS2').addEventListener('click',()=>{editor.value=starterHtmlS2;render();status.textContent='Exemple inicial recuperat'});editor.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();render()}})}
function showAea2S2(key){const d=aea2S2Tabs[key],hint=d.hint?`<button class="hint-button" type="button">Mostra una pista</button><div class="hint">${d.hint}</div>`:'';document.querySelector('#aea2S2Content').innerHTML=`<div class="stage-head"><div><p class="overline">${d.tag}</p><h3>${d.title}</h3></div></div><div class="stage-meta">${d.meta.map(x=>`<span>${x}</span>`).join('')}</div><p class="instruction">${d.intro}</p>${d.visual||''}<ol class="step-list">${d.steps.map(x=>`<li>${x}</li>`).join('')}</ol>${hint}<div class="lesson-boxes"><div class="lesson-box"><b>Què has de produir?</b><span>${d.deliver}</span></div><div class="lesson-box success"><b>Criteri d’èxit</b><span>${d.success}</span></div></div>`;document.querySelectorAll('[data-aea2-s2-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.aea2S2Tab===key));const hb=document.querySelector('#aea2S2Content .hint-button');if(hb)hb.addEventListener('click',()=>{const h=document.querySelector('#aea2S2Content .hint');h.classList.toggle('visible');hb.textContent=h.classList.contains('visible')?'Amaga la pista':'Mostra una pista'});document.querySelectorAll('#aea2S2Content [data-copy-code]').forEach(button=>button.addEventListener('click',async()=>{const code=document.getElementById(button.dataset.copyCode)?.textContent||'';try{await navigator.clipboard.writeText(code);button.textContent='Codi copiat ✓'}catch{button.textContent='Selecciona i copia manualment'}}));if(key==='lab')activateHtmlLabS2()}
document.querySelectorAll('[data-aea2-s2-tab]').forEach(b=>b.addEventListener('click',()=>{showAea2S2(b.dataset.aea2S2Tab);document.querySelector('#aea2S2Content').focus()}));showAea2S2('mission');

