function activateRouteLabS3(){let current=0,answered=false;const count=document.querySelector('#routeCountS3'),question=document.querySelector('#routeQuestionS3'),context=document.querySelector('#routeContextS3'),options=document.querySelector('#routeOptionsS3'),next=document.querySelector('#nextRouteS3'),status=document.querySelector('#routeStatusS3');if(!count||!question||!options||!next)return;const render=()=>{answered=false;next.disabled=true;status.textContent='';const d=routeQuestionsS3[current];count.textContent=`RUTA ${current+1} / ${routeQuestionsS3.length}`;question.textContent=d.q;context.textContent=d.c;options.innerHTML=d.o.map((x,i)=>`<button type="button" data-route-option="${i}"><code>${x}</code></button>`).join('');options.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{if(answered)return;answered=true;const chosen=Number(b.dataset.routeOption),ok=chosen===d.a;b.classList.add(ok?'correct':'incorrect');options.querySelectorAll('button')[d.a].classList.add('correct');status.textContent=ok?'Correcte: la ruta surt del fitxer actual.':'Revisa quantes carpetes has de pujar o baixar.';next.disabled=false}))};next.addEventListener('click',()=>{if(current<routeQuestionsS3.length-1){current++;render()}else{status.textContent='Laboratori completat: 4 rutes revisades.';next.disabled=true}});render()}
function showAea2S3(key){const d=aea2S3Tabs[key],hint=d.hint?`<button class="hint-button" type="button">Mostra una pista</button><div class="hint">${d.hint}</div>`:'';document.querySelector('#aea2S3Content').innerHTML=`<div class="stage-head"><div><p class="overline">${d.tag}</p><h3>${d.title}</h3></div></div><div class="stage-meta">${d.meta.map(x=>`<span>${x}</span>`).join('')}</div><p class="instruction">${d.intro}</p>${d.visual||''}<ol class="step-list">${d.steps.map(x=>`<li>${x}</li>`).join('')}</ol>${hint}<div class="lesson-boxes"><div class="lesson-box"><b>Què has de produir?</b><span>${d.deliver}</span></div><div class="lesson-box success"><b>Criteri d’èxit</b><span>${d.success}</span></div></div>`;document.querySelectorAll('[data-aea2-s3-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.aea2S3Tab===key));const hb=document.querySelector('#aea2S3Content .hint-button');if(hb)hb.addEventListener('click',()=>{const h=document.querySelector('#aea2S3Content .hint');h.classList.toggle('visible');hb.textContent=h.classList.contains('visible')?'Amaga la pista':'Mostra una pista'});if(key==='lab')activateRouteLabS3()}
document.querySelectorAll('[data-aea2-s3-tab]').forEach(b=>b.addEventListener('click',()=>{showAea2S3(b.dataset.aea2S3Tab);document.querySelector('#aea2S3Content').focus()}));showAea2S3('mission');

const aea2TeacherTabsS1={
 overview:{tag:'ABANS D’OBRIR LA SESSIÓ',title:'Què és aquesta sessió i què necessites?',intro:'Primera entrada a l’HTML: l’alumnat aprèn el circuit editor → desa → navegador → actualitza, identifica l’estructura bàsica i acaba reparant un document avariat.',body:'<div class="teacher-summary"><article><b>Objectiu</b><span>Entendre l’estructura abans d’acumular etiquetes.</span></article><article><b>Agrupament</b><span>Pràctica individual i contrast final per parelles.</span></article><article><b>Lliurable</b><span>Un ZIP amb tres HTML i un registre breu.</span></article><article><b>Material</b><span>Editor de text pla, navegador i Classroom.</span></article></div><div class="teacher-callout"><b>Decisió didàctica</b><p>No comencen amb un fitxer buit: primer proven un exemple mínim, després creen el seu index.html i finalment reparen codi incorrecte.</p></div>',footer:'Durada prevista: 165 minuts. La pausa es pot inserir durant el projecte sense trencar la seqüència.'},
 run:{tag:'CONDUCCIÓ · 165 MIN',title:'Guió per fer classe sense improvisar',intro:'La sessió alterna demostració breu, pràctica individual i contrast per parelles. La pausa oficial es pot inserir al minut 110, durant el projecte, sense alterar l’ordre.',body:'<div class="teacher-timeline"><article><b>0–10 · Missió</b><p>Projecta l’encàrrec. Digues: «Avui no busquem una web bonica; busquem una estructura que tingui sentit». L’alumnat només prepara quatre textos.</p><em>Observa si diferencia contingut i codi.</em></article><article><b>10–30 · Prepara’t</b><p>Modela una vegada el cicle editor → Ctrl+S → navegador → Ctrl+R. Comprova especialment l’extensió .html i la codificació UTF-8.</p><em>No resolguis problemes de ruta sense demanar abans quin fitxer han desat.</em></article><article><b>30–45 · Radiografia</b><p>Dibuixa html com la capsa gran i head/body com dues zones germanes. Contrasta title amb h1.</p><em>Pregunta: «Això ho sap el navegador o ho veu la persona?»</em></article><article><b>45–80 · Laboratori</b><p>Demana canvis d’un en un. Abans de cada execució, l’alumne ha de predir què canviarà.</p><em>Si es bloqueja, recupera l’exemple i redueix el canvi a una sola etiqueta.</em></article><article><b>80–120 · Projecte</b><p>Creació individual d’index.html. Permet consultar la guia. A la meitat, revisió creuada de 2 minuts: cada parella assenyala d’on surt cada text.</p><em>La pausa del centre pot situar-se al minut 110.</em></article><article><b>120–150 · Repte</b><p>Treball per parelles. Primer diagnostiquen sense editar; després reparen de fora cap a dins.</p><em>Dona les pistes en ordre: estructura, jerarquia, tancaments.</em></article><article><b>150–165 · Lliurament</b><p>Comprovació dels tres HTML, registre breu, compressió i entrega al Classroom.</p><em>Obre un ZIP de mostra perquè vegin l’estructura esperada.</em></article></div>',footer:'Preparació prèvia: navegador, editor de text pla o VS Code, accés al Classroom i una carpeta ZIP de mostra. No cal servidor web.'},
 solutions:{tag:'SOLUCIONS I RESPOSTES ESPERADES',title:'Models per orientar i corregir',intro:'No hi ha una única targeta vàlida: el contingut de l’esdeveniment és lliure. Sí que hi ha condicions estructurals comunes i una solució de referència per al repte.',body:'<div class="solution-grid"><section><h4>Prova guiada</h4><p>És correcta si manté l’estructura facilitada i modifica almenys l’h1 i el paràgraf. No cal puntuar-ne l’originalitat.</p><pre><code>&lt;h1&gt;La meva primera web&lt;/h1&gt;\n&lt;p&gt;Ja sé desar i actualitzar HTML.&lt;/p&gt;</code></pre></section><section><h4>Projecte index.html</h4><p>Accepta qualsevol temàtica adequada. Ha d’incloure doctype, lang, charset, title, un únic h1, almenys un h2, dos paràgrafs i un comentari útil.</p><pre><code>&lt;!-- Informació principal de l’esdeveniment --&gt;</code></pre></section></div><section class="full-solution"><h4>Solució de referència · repte_reparat.html</h4><pre><code>&lt;!doctype html&gt;\n&lt;html lang="ca"&gt;\n  &lt;head&gt;\n    &lt;meta charset="utf-8"&gt;\n    &lt;title&gt;PixelFest&lt;/title&gt;\n  &lt;/head&gt;\n  &lt;body&gt;\n    &lt;h1&gt;PixelFest 2027&lt;/h1&gt;\n    &lt;p&gt;Una jornada de videojocs i creativitat digital.&lt;/p&gt;\n    &lt;h2&gt;Programa de la tarda&lt;/h2&gt;\n    &lt;p&gt;Competició retro, taller de píxel art i música.&lt;/p&gt;\n    &lt;p&gt;Aula 110 · Entrada lliure&lt;/p&gt;\n  &lt;/body&gt;\n&lt;/html&gt;</code></pre><p><b>Variants vàlides:</b> el darrer paràgraf pot anar abans del programa; es poden afegir comentaris; el title pot ser més descriptiu. No és vàlid mantenir dos h1 sense una justificació estructural clara en aquesta activitat inicial.</p></section>',footer:'Error important a comentar: el navegador intenta reparar HTML incorrecte. Que «es vegi» no significa que el codi estigui ben estructurat.'},
 assessment:{tag:'AVALUACIÓ FORMATIVA',title:'Corregir amb criteri i en poc temps',intro:'Aquesta sessió genera evidències de l’RA2, però no cal convertir cada microtasca en una nota. Utilitza la pauta sobre 10 per donar feedback i alimentar els instruments globals de l’AEA2.',body:'<div class="quick-rubric"><article><b>3 punts · Estructura</b><span>doctype, html, head i body ben ordenats; title i contingut al lloc correcte.</span></article><article><b>2 punts · Etiquetes i atributs</b><span>Un h1, jerarquia coherent, paràgrafs tancats, lang i charset adequats.</span></article><article><b>2 punts · Codi llegible</b><span>Tabulació consistent, noms correctes i comentari que aporta informació.</span></article><article><b>2 punts · Reparació raonada</b><span>El registre relaciona problemes, canvis i comprovacions reals.</span></article><article><b>1 punt · Lliurament professional</b><span>ZIP ben anomenat, quatre fitxers accessibles i entrega dins del termini.</span></article></div><div class="ce-map"><h4>CE observables en aquesta sessió</h4><p><b>Principals:</b> 2.1, 2.2, 2.3, 2.4, 2.5, 2.6, 2.7, 2.9, 2.10 i 2.11.</p><p><b>Transversals observables:</b> 2.12, 2.14, 2.15, 2.16 i 2.17.</p><p><b>Encara no són objectiu central:</b> 2.8 —enllaços— i 2.13 —documentació tècnica en anglès— es treballaran en sessions posteriors.</p></div>',footer:'Feedback recomanat: una fortalesa concreta + un error prioritari + una acció de millora. Evita corregir deu detalls alhora.'},
 materials:{tag:'MATERIALS DE LA SESSIÓ',title:'Tot el que cal projectar, repartir i recollir',intro:'Els materials de l’alumnat són a la mateixa web. Des d’aquí pots revisar exactament què veuran i baixar els fitxers de partida abans de la classe.',body:'<div class="teacher-downloads"><a href="#aea2-lab"><b>Obre la vista de l’alumnat</b><span>Missió, pràctica, repte, lliurament i guia HTML →</span></a><a href="downloads/AEA2_S1_prova_guiada.html" download><b>Exemple guiat</b><span>prova_guiada.html ↓</span></a><a href="downloads/AEA2_S1_repte_avariat.html" download><b>Codi del repte</b><span>repte_avariat.html ↓</span></a><a href="downloads/AEA2_S1_registre.txt" download><b>Plantilla del registre</b><span>registre.txt ↓</span></a></div>',footer:'Abans de la sessió, comprova els quatre recursos des del mateix ordinador que utilitzarà el professorat.'}
};
aea2TeacherTabsS1.overview={tag:'ABANS D’OBRIR LA SESSIÓ',title:'Fonaments, primera prova i projecte propi',intro:'Primera entrada a l’HTML. L’alumnat entén què són la WWW, el client i el servidor; després practica el circuit editor → desa → navegador → actualitza, identifica l’estructura i repara un document avariat.',body:'<div class="teacher-summary"><article><b>Objectiu</b><span>Relacionar el funcionament web amb un primer document HTML.</span></article><article><b>Agrupament</b><span>Explicació breu, pràctica individual i contrast per parelles.</span></article><article><b>Lliurable</b><span>Un ZIP amb tres HTML i un registre breu.</span></article><article><b>Material</b><span>Presentació, editor de text pla, navegador i Classroom.</span></article></div><div class="teacher-callout"><b>Idea que ha de quedar clara</b><p>El navegador no rep una captura de la web: rep fitxers, interpreta l’HTML i construeix el document visible.</p></div>',footer:'Durada prevista: 165 minuts. La teoria ocupa 15 minuts i es recupera durant la pràctica.'};
aea2TeacherTabsS1.run={tag:'CONDUCCIÓ · 165 MIN',title:'Guió de la sessió 1 amb la teoria integrada',intro:'La càpsula inicial dona sentit a la pràctica. Evita ampliar-la amb una classe magistral: formula preguntes i recupera els conceptes quan apareguin al codi.',body:'<div class="teacher-timeline"><article><b>0–15 · Fonaments</b><p>Utilitza la mini-presentació. Diferencia Internet/WWW i representa client → petició → servidor → resposta → navegador.</p><em>Pregunta: «El servidor ens envia una fotografia?»</em></article><article><b>15–25 · Missió</b><p>Presenta la targeta web. L’alumnat prepara quatre textos, sense programar.</p><em>Observa si diferencia contingut i codi.</em></article><article><b>25–45 · Prepara’t</b><p>Modela el cicle editor → Ctrl+S → navegador → Ctrl+R. Comprova extensió .html i UTF-8.</p><em>Demana sempre quin fitxer han desat i quin han obert.</em></article><article><b>45–60 · Radiografia</b><p>Dibuixa html com la capsa gran i head/body com dues zones germanes. Contrasta title amb h1.</p><em>Pregunta: «Ho sap el navegador o ho veu la persona?»</em></article><article><b>60–90 · Laboratori</b><p>Canvis d’un en un i predicció abans d’executar.</p><em>Si es bloqueja, recupera l’exemple.</em></article><article><b>90–125 · Projecte</b><p>Creació individual d’index.html amb consulta de la guia. La pausa pot situar-se al minut 110.</p><em>Fes una revisió creuada de dos minuts.</em></article><article><b>125–150 · Repte</b><p>Diagnòstic sense editar i reparació de fora cap a dins.</p><em>Pistes: estructura, jerarquia i tancaments.</em></article><article><b>150–165 · Lliurament</b><p>Comprovació, registre, ZIP i entrega.</p><em>Obre un ZIP de mostra.</em></article></div>',footer:'Preparació: presentació de fonaments, navegador, editor de text pla, Classroom i una carpeta ZIP de mostra. No cal servidor web.'};
aea2TeacherTabsS1.materials={tag:'MATERIALS DE LA SESSIÓ',title:'Tot el necessari per explicar, practicar i recollir',intro:'La teoria i la pràctica comparteixen els mateixos exemples. Descarrega els materials abans de la classe i comprova’ls des de l’ordinador docent.',body:'<div class="teacher-downloads"><a href="downloads/AEA2_S1_Fonaments_web.pptx" download><b>Presentació de fonaments</b><span>Història, client-servidor i fitxers · PPTX ↓</span></a><a href="downloads/AEA2_Conceptes_web_resum.pdf" download><b>Resum de conceptes</b><span>Consulta per a l’alumnat · PDF ↓</span></a><a href="downloads/AEA2_S1_prova_guiada.html" download><b>Exemple guiat</b><span>prova_guiada.html ↓</span></a><a href="downloads/AEA2_S1_repte_avariat.html" download><b>Codi del repte</b><span>repte_avariat.html ↓</span></a><a href="downloads/AEA2_S1_registre.txt" download><b>Plantilla del registre</b><span>registre.txt ↓</span></a><a href="#aea2-lab"><b>Vista de l’alumnat</b><span>Obre la sessió interactiva →</span></a></div>',footer:'Abans de començar, comprova que el navegador permet obrir fitxers locals i que es veuen les extensions.'};

const aea2TeacherTabsS2={
 overview:{tag:'VISIÓ RÀPIDA · SESSIÓ 2',title:'Contingut amb sentit',intro:'L’alumnat continua el mateix index.html i aprèn a representar la jerarquia del contingut amb h1, h2, h3, paràgrafs, strong, em i comentaris útils.',body:'<div class="teacher-summary"><article><b>Objectiu</b><span>Triar etiquetes pel significat, no per la mida visual.</span></article><article><b>Agrupament</b><span>Creació individual, contrast i repte per parelles.</span></article><article><b>Lliurable</b><span>ZIP amb dues versions, repte reparat i registre.</span></article><article><b>Material</b><span>Web, presentació, editor, navegador i fitxers de partida.</span></article></div><div class="teacher-callout"><b>Missatge central</b><p>Un h2 no vol dir «text gran»: vol dir «aquí comença un apartat del tema principal».</p></div>',footer:'CE principals: 2.1, 2.2, 2.3, 2.4, 2.5, 2.6, 2.10, 2.11, 2.12, 2.16 i 2.17.'},
 run:{tag:'CONDUCCIÓ · 165 MIN',title:'Guió operatiu de la sessió 2',intro:'Cada explicació es comprova immediatament en un exemple o en el projecte. La pausa es pot inserir durant el projecte, aproximadament al minut 110.',body:'<div class="teacher-timeline"><article><b>0–10 · Missió</b><p>Obren index.html, creen index_s1.html i expliquen què ha d’entendre primer el visitant.</p><em>Comprova que treballen sobre una còpia segura.</em></article><article><b>10–30 · Idea clau</b><p>Projecta la jerarquia h1 → h2 → h3 i diferencia p, strong i em.</p><em>No parlis de mida o negreta com a criteri principal.</em></article><article><b>30–45 · Model</b><p>Transformeu textos solts en una estructura. Demana una decisió abans de mostrar cada etiqueta.</p><em>Pregunta: «Obre un apartat o explica una idea?»</em></article><article><b>45–75 · Laboratori</b><p>Un canvi cada vegada, predicció i execució.</p><em>Fes corregir el primer salt de jerarquia detectat.</em></article><article><b>75–120 · Projecte</b><p>Milloren el seu index.html. Al minut 100, revisió de jerarquia per parelles sense editar.</p><em>La pausa pot anar al minut 110.</em></article><article><b>120–145 · Repte</b><p>Reparen PixelFest conservant tot el contingut.</p><em>Primer cinc problemes; després edició.</em></article><article><b>145–165 · Lliurament</b><p>Comparen versions, completen registre, comprimeixen i entreguen.</p><em>Obre almenys un ZIP abans de donar per acabat.</em></article></div>',footer:'Si falta temps, acaba el repte en la sessió següent; no eliminis la comparació entre index_s1.html i index.html.'},
 solutions:{tag:'SOLUCIONS I RESPOSTES ESPERADES',title:'Què és correcte i què pot variar?',intro:'El contingut del projecte és lliure, però la jerarquia ha de ser explicable. El repte disposa d’una solució de referència, no d’un únic estil de redacció.',body:'<div class="solution-grid"><section><h4>Projecte index.html</h4><p>Ha de tenir un únic h1, almenys dos h2, tres paràgrafs, strong, em, dos comentaris útils i tabulació consistent. Un h3 només és necessari quan existeix un subapartat real.</p></section><section><h4>Comentaris útils</h4><p>Accepta comentaris com «Inici del programa de tallers». No acceptis «text», «aquí» o comentaris que només repeteixen l’etiqueta.</p></section></div><section class="full-solution"><h4>Solució de referència · repte_jerarquia_reparat.html</h4><pre><code>&lt;!doctype html&gt;\n&lt;html lang="ca"&gt;\n  &lt;head&gt;\n    &lt;meta charset="utf-8"&gt;\n    &lt;title&gt;PixelFest&lt;/title&gt;\n  &lt;/head&gt;\n  &lt;body&gt;\n    &lt;!-- Presentació de l’esdeveniment --&gt;\n    &lt;h1&gt;PixelFest 2027&lt;/h1&gt;\n    &lt;p&gt;Una jornada digital.&lt;/p&gt;\n    &lt;!-- Informació del programa --&gt;\n    &lt;h2&gt;Programa&lt;/h2&gt;\n    &lt;p&gt;Arcade, píxel art i música.&lt;/p&gt;\n    &lt;h3&gt;Inscripció&lt;/h3&gt;\n    &lt;p&gt;Reserva &lt;strong&gt;avui&lt;/strong&gt; la teva plaça.&lt;/p&gt;\n  &lt;/body&gt;\n&lt;/html&gt;</code></pre></section>',footer:'Variant vàlida: «Inscripció» pot ser h2 si és un apartat germà de «Programa». En aquest cas cal poder justificar la decisió.'},
 assessment:{tag:'AVALUACIÓ FORMATIVA',title:'Pocs indicadors, però observables',intro:'No puntuis cada prova del laboratori. Revisa el producte final, la reparació i dues decisions documentades.',body:'<div class="quick-rubric"><article><b>3 punts · Jerarquia</b><span>Un h1; h2 i h3 amb una dependència coherent.</span></article><article><b>2 punts · Text</b><span>Paràgrafs complets i strong/em amb significat.</span></article><article><b>2 punts · Codi</b><span>Tancaments, comentaris i tabulació llegible.</span></article><article><b>2 punts · Reparació</b><span>Detecta problemes i explica els canvis.</span></article><article><b>1 punt · Lliurament</b><span>Versions conservades, noms correctes i ZIP accessible.</span></article></div><div class="ce-map"><h4>Traçabilitat curricular</h4><p><b>Directes:</b> 2.1 estructura; 2.2 comentaris; 2.3 tabulació; 2.4 etiquetes; 2.5 i 2.6 atributs i valors.</p><p><b>Procés:</b> 2.10 temps i metodologia; 2.11 documentació; 2.12 consulta; 2.16 iniciativa; 2.17 autonomia.</p></div>',footer:'Feedback recomanat: una decisió de jerarquia encertada + el primer error estructural que cal corregir + una acció concreta.'},
 materials:{tag:'MATERIALS DE LA SESSIÓ 2',title:'Recursos coordinats per a alumnat i professorat',intro:'La vista web conté les instruccions completes. Els PDF serveixen per imprimir, recuperar una absència o revisar sense connexió.',body:'<div class="teacher-downloads"><a href="#aea2-s2"><b>Vista de l’alumnat</b><span>Sessió interactiva completa →</span></a><a href="downloads/AEA2_S2_Presentacio.pptx" download><b>Presentació d’aula</b><span>Mini-lliçó i consignes · PPTX ↓</span></a><a href="downloads/AEA2_S2_Guia_alumnat.pdf" download><b>Guia de l’alumnat</b><span>Enunciats i comprovacions · PDF ↓</span></a><a href="downloads/AEA2_S2_Guia_docent.pdf" download><b>Guia docent</b><span>Guió, solucions i avaluació · PDF ↓</span></a><a href="downloads/AEA2_S2_base.html" download><b>Base per absències</b><span>Fitxer HTML de partida ↓</span></a><a href="downloads/AEA2_S2_repte_jerarquia.html" download><b>Repte avariat</b><span>Codi per reparar ↓</span></a><a href="downloads/AEA2_S2_registre.txt" download><b>Registre</b><span>Plantilla de decisions i reparacions ↓</span></a><a href="downloads/AEA2_Conceptes_web_resum.pdf" download><b>Conceptes web</b><span>Resum permanent · PDF ↓</span></a></div>',footer:'Prova els fitxers HTML en local abans de la classe i confirma que les extensions són visibles.'}
};
const aea2TeacherTabsS3={
 overview:{tag:'ABANS D’OBRIR LA SESSIÓ',title:'Tres pàgines, una navegació i rutes que es poden explicar',intro:'La sessió converteix el document creat a les sessions 1 i 2 en un petit lloc web. L’alumnat dedueix rutes des de l’origen, les prova sistemàticament i repara un projecte amb carpetes.',body:'<div class="teacher-summary"><article><b>Objectiu</b><span>Crear i verificar enllaços interns, externs i fragments.</span></article><article><b>Agrupament</b><span>Model guiat, projecte individual i repte per parelles.</span></article><article><b>Lliurable</b><span>Un ZIP amb el lloc, el repte reparat i el registre.</span></article><article><b>CE directes</b><span>2.5, 2.6, 2.7 i 2.8.</span></article></div><div class="teacher-callout"><b>Idea que ha de quedar clara</b><p>Una ruta relativa no depèn de l’ordinador ni de la memòria: es calcula des del fitxer que conté l’enllaç.</p></div>',footer:'No introdueixis servidors ni publicació. Tota la sessió funciona amb fitxers locals.'},
 run:{tag:'CONDUCCIÓ · 165 MIN',title:'Guió de la sessió 3, pas a pas',intro:'Modela sempre l’origen i la destinació abans d’escriure href. Quan una ruta falla, demana que dibuixin les carpetes i evita la prova aleatòria.',body:'<div class="teacher-timeline"><article><b>0–10 · Missió</b><p>Presenta el mapa de tres pàgines i el lliurable. Comproven index.html i creen index_s2.html.</p><em>Pregunta: «Què hauria d’explicar cada pàgina?»</em></article><article><b>10–30 · Idea clau</b><p>Desmunta a, href, destinació i text clicable. Contrasta mateixa carpeta, ../, URL completa i fragment.</p><em>Repeteix: «La ruta surt d’on soc».</em></article><article><b>30–50 · Model</b><p>Mostra tres fitxers germans i una nav idèntica. Analitza noms, majúscules i text descriptiu.</p><em>Canvia una lletra i demana una predicció.</em></article><article><b>50–75 · Laboratori</b><p>Resolució individual de quatre rutes; després justificació en parelles.</p><em>No acceptis només «és la segona»: demana el recorregut.</em></article><article><b>75–120 · Projecte</b><p>Creen programa.html i contacte.html, afegeixen nav, fragment i enllaç extern. Revisió creuada al minut 105.</p><em>Proven totes les pàgines, no només index.html.</em></article><article><b>120–145 · Repte</b><p>Descomprimeixen Campus Byte, diagnostiquen cinc avaries i reparen sense moure fitxers.</p><em>Primer registre; després edició.</em></article><article><b>145–165 · Lliurament</b><p>Comprimeixen la carpeta, la descomprimeixen en un altre lloc i tornen a provar-la.</p><em>Aquesta prova detecta rutes que només funcionaven per accident.</em></article></div>',footer:'Pausa flexible: després del laboratori o durant la construcció del projecte.'},
 solutions:{tag:'SOLUCIONS I RESPOSTES ESPERADES',title:'Rutes correctes i diagnòstic del repte Campus Byte',intro:'El projecte propi admet continguts diferents, però la navegació ha de complir les mateixes condicions. El repte té cinc reparacions concretes.',body:'<div class="solution-grid"><section><h4>Mateixa carpeta</h4><pre><code>href="index.html"\nhref="programa.html"\nhref="contacte.html"</code></pre><p>Funcionen igual als tres documents perquè són germans.</p></section><section><h4>Fragment i URL externa</h4><pre><code>href="#horaris"\nid="horaris"\nhref="https://developer.mozilla.org/"</code></pre><p>El valor del fragment ha de coincidir exactament amb l’id.</p></section><section><h4>Repte · index.html</h4><p><code>programa.html</code> → <code>pagines/programa.html</code>. <code>#horaris</code> → <code>pagines/programa.html#horaris</code>.</p></section><section><h4>Repte · pàgines internes</h4><p>Des de programa: inici = <code>../index.html</code>; contacte = <code>../contacte/contacte.html</code>. Des de contacte: inici = <code>../index.html</code>.</p></section></div><div class="teacher-callout"><b>Comprovació del fragment</b><p>A programa.html l’apartat ja té <code>id="horaris"</code>. L’alumnat ha de conservar-lo i fer que l’enllaç d’index.html arribi fins a aquest punt.</p></div>',footer:'No penalitzis l’ús de ./ davant d’un fitxer germà si la ruta funciona i l’alumne la pot explicar.'},
 assessment:{tag:'AVALUACIÓ FORMATIVA',title:'Pauta breu sobre 10 punts',intro:'Valora que el lloc es pugui transportar, navegar i entendre. Una pàgina visualment correcta amb rutes trencades no està completada.',body:'<div class="quick-rubric"><article><b>2 punts · Navegació</b><span>Nav present i coherent a les tres pàgines.</span></article><article><b>2 punts · Rutes</b><span>Enllaços interns correctes des de tots els orígens.</span></article><article><b>2 punts · Tipus d’enllaç</b><span>Fragment i URL externa ben aplicats.</span></article><article><b>2 punts · Reparació</b><span>Cinc avaries diagnosticades i corregides.</span></article><article><b>1 punt · Organització</b><span>Noms i estructura de carpeta coherents.</span></article><article><b>1 punt · Registre</b><span>Decisions, proves i lliurament comprensibles.</span></article></div><div class="ce-map"><h4>Traçabilitat curricular</h4><p><b>Directes:</b> 2.5 atributs; 2.6 valors; 2.7 organització de fitxers; 2.8 enllaços.</p><p><b>Procés:</b> 2.3 indentació; 2.10 metodologia; 2.11 documentació; 2.12 consulta; 2.14–2.17 relacions, equip, iniciativa i autonomia.</p></div>',footer:'Feedback recomanat: una ruta ben deduïda + el primer enllaç que falla + el recorregut correcte explicat amb paraules.'},
 materials:{tag:'MATERIALS DE LA SESSIÓ 3',title:'Recursos coordinats per explicar, construir i reparar',intro:'La web conté les instruccions completes. Descarrega abans de classe el repte ZIP i comprova que es pot descomprimir a l’entorn de l’alumnat.',body:'<div class="teacher-downloads"><a href="#aea2-s3"><b>Vista de l’alumnat</b><span>Sessió interactiva completa →</span></a><a href="downloads/AEA2_S3_Presentacio.pptx" download><b>Presentació d’aula</b><span>Enllaços i rutes · PPTX ↓</span></a><a href="downloads/AEA2_S3_Guia_alumnat.pdf" download><b>Guia de l’alumnat</b><span>Enunciats i comprovacions · PDF ↓</span></a><a href="downloads/AEA2_S3_Guia_docent.pdf" download><b>Guia docent</b><span>Guió, solucions i avaluació · PDF ↓</span></a><a href="downloads/AEA2_S3_programa_base.html" download><b>Base programa.html</b><span>Plantilla recuperable ↓</span></a><a href="downloads/AEA2_S3_contacte_base.html" download><b>Base contacte.html</b><span>Plantilla recuperable ↓</span></a><a href="downloads/AEA2_S3_repte_rutes.zip" download><b>Campus Byte avariat</b><span>Repte de reparació · ZIP ↓</span></a><a href="downloads/AEA2_S3_registre.txt" download><b>Registre</b><span>Plantilla de decisions i proves ↓</span></a></div>',footer:'No distribueixis les solucions. Conserva-les a la vista docent i a la guia docent.'}
};
let aea2TeacherSession='s1';
function showAea2Teacher(key){const sources={s1:aea2TeacherTabsS1,s2:aea2TeacherTabsS2,s3:aea2TeacherTabsS3},d=sources[aea2TeacherSession][key];document.querySelector('#aea2TeacherContent').innerHTML=`<p class="teacher-kicker">${d.tag}</p><h3>${d.title}</h3><p class="teacher-intro">${d.intro}</p>${d.body}<footer>${d.footer}</footer>`;document.querySelectorAll('[data-aea2-teacher]').forEach(b=>b.classList.toggle('selected',b.dataset.aea2Teacher===key))}
document.querySelectorAll('[data-aea2-teacher]').forEach(b=>b.addEventListener('click',()=>showAea2Teacher(b.dataset.aea2Teacher)));
document.querySelectorAll('[data-aea2-teacher-session]').forEach(b=>b.addEventListener('click',()=>{aea2TeacherSession=b.dataset.aea2TeacherSession;document.querySelectorAll('[data-aea2-teacher-session]').forEach(x=>x.classList.toggle('selected',x===b));const labels={s1:'La web per dins · guia docent',s2:'Contingut amb sentit · guia docent',s3:'Connecta les pàgines · guia docent'};document.querySelector('#aea2TeacherLabel').textContent=`AEA2 · SESSIÓ ${aea2TeacherSession.slice(1)}`;document.querySelector('#aea2-teacher-title').textContent=labels[aea2TeacherSession];showAea2Teacher('overview')}));
showAea2Teacher('overview');

const teacherGuides={
 'aea0-overview':{tag:'VISIÓ RÀPIDA',title:'Una diagnosi activa, sense nota numèrica',intro:'L’AEA0 presenta el mòdul i permet observar com l’alumnat ordena instruccions, descompon problemes, coopera i reacciona davant l’error.',body:'<div class="teacher-summary"><article><b>Durada</b><span>165 minuts · una sessió</span></article><article><b>Agrupament</b><span>Equips de 4 amb rols rotatius</span></article><article><b>Evidència</b><span>Produccions d’equip + passaport individual</span></article><article><b>Caràcter</b><span>Diagnòstic, formatiu i sense qualificació</span></article></div>',footer:'La guia docent completa concreta què preparar, què dir, què observar i com adaptar cada repte.'},
 'aea0-run':{tag:'CONDUCCIÓ · 165 MIN',title:'Seqüència recomanada',intro:'La sessió combina demostració breu, manipulació i tancament individual. La graella buida permet reutilitzar el material sense afegir pantalles.',body:'<div class="teacher-timeline"><article><b>0–15 · Entrada i demostració</b><p>Presenta NEO, els rols i les ordres. Modela girar i avançar sense resoldre el laberint.</p><em>Comprova que diferencien gir i desplaçament.</em></article><article><b>15–55 · Fases 1 i 2</b><p>Resolució de l’anada i construcció del retorn continu, conservant l’orientació a F2.</p><em>Fes executar literalment; no recol·loquis NEO.</em></article><article><b>55–95 · Fase 3</b><p>Creació, validació, intercanvi, execució i canvi d’un obstacle.</p><em>Un sol intercanvi evita dispersió.</em></article><article><b>95–135 · Capsa negra i Incidència 110</b><p>Infereixen una regla i després classifiquen actuacions amb justificació.</p><em>Valora el criteri, no només la categoria.</em></article><article><b>135–165 · Passaport i sortida</b><p>Tancament individual i recollida ordenada de peces.</p><em>Conserva aquesta evidència encara que falti temps.</em></article></div>',footer:'Consulta el minutatge literal i les variants a la guia docent operativa.'},
 'aea0-solutions':{tag:'SOLUCIONARI',title:'Respostes i criteris, separats del material de l’alumnat',intro:'Els reptes poden tenir més d’una resposta vàlida. El solucionari indica models, condicions mínimes i preguntes per comprovar el raonament.',body:'<div class="teacher-callout"><b>Referència validada</b><p>Missió 01: l’anada mínima de B5 a F2 necessita 15 targetes. El recorregut continu d’anada i tornada necessita 32 targetes; NEO conserva a F2 la posició i l’orientació. Fase 3: valida 10–14 obstacles, ruta provada, tres girs mínims, carreró aparent i correcció del primer error.</p></div><div class="teacher-downloads"><a href="downloads/AEA0_Solucionari_docent_A4.pdf" download><b>Solucionari docent AEA0</b><span>Seqüències, criteris i observació · PDF ↓</span></a></div>',footer:'No mostris el solucionari durant l’execució. Utilitza’l per conduir la posada en comú i reconèixer variants justificades.'},
 'aea0-assessment':{tag:'OBSERVACIÓ DIAGNÒSTICA',title:'Registrar poc, però que sigui útil',intro:'No cal puntuar totes les accions. Tria moments observables i anota evidències breus amb l’escala A / PA / NO.',body:'<div class="teacher-summary"><article><b>A · Assolit</b><span>Ho fa de manera autònoma i ho explica.</span></article><article><b>PA · Parcial</b><span>Ho fa amb ajuda o explicació incompleta.</span></article><article><b>NO · No observat</b><span>No hi ha prou evidència; no equival a suspès.</span></article></div><div class="teacher-callout"><b>Indicadors prioritaris</b><p>Ordena instruccions, detecta una desviació, proposa una correcció, separa un problema en parts i participa amb una aportació observable.</p></div>',footer:'La graella diagnòstica completa i els CE associats són a les pàgines finals de la guia docent.'},
 'aea0-materials':{tag:'PAQUET COMPLET',title:'Projecta, reparteix i conserva',intro:'El tauler A3 és una graella reutilitzable: NEO, bateria i obstacles són peces independents. El mateix joc serveix per a la Missió 01 i per als reptes creats pels equips.',body:'<div class="teacher-downloads"><a href="downloads/AEA0_Guia_docent_operativa.pdf" download><b>Guia docent operativa</b><span>Guió complet · PDF ↓</span></a><a href="downloads/AEA0_Presentacio_visual_aula.pptx" download><b>Presentació d’aula</b><span>18 diapositives editables · PPTX ↓</span></a><a href="downloads/AEA0_Kit_equips_A4.pdf" download><b>Kit dels equips</b><span>NEO, bateria, 16 obstacles i ordres · PDF ↓</span></a><a href="downloads/AEA0_Taulers_A3.pdf" download><b>Taulers i configuració</b><span>Graella buida + Missió 01 + Incidència 110 · PDF ↓</span></a><a href="downloads/AEA0_Passaport_alumnat.pdf" download><b>Passaport individual</b><span>Diagnosi i sortida · PDF ↓</span></a></div>',footer:'Imprimeix els taulers al 100% i plastifica la graella. Les peces funcionen millor en cartolina de 200–250 g.'},
 'aea1-overview':{tag:'VISIÓ RÀPIDA · SESSIÓ 1',title:'Desmuntem el problema',intro:'Primera de quatre sessions de l’AEA1. L’alumnat practica perspectives, abstracció, classificació, descomposició i comprovació abans de programar.',body:'<div class="teacher-summary"><article><b>Durada</b><span>165 minuts</span></article><article><b>Agrupament</b><span>Equips de 4 amb tancament individual</span></article><article><b>Lliurable</b><span>Fitxes 1–3 + bitllet de sortida</span></article><article><b>CE observables</b><span>1.1–1.4, 1.6, 1.8 i 1.9</span></article></div>',footer:'La guia de l’alumnat i la guia docent estan sincronitzades per pàgina, temps i evidència.'},
 'aea1-run':{tag:'CONDUCCIÓ · 165 MIN',title:'Què passa a cada bloc?',intro:'L’alumnat comença individualment, contrasta en equip i tanca amb una evidència pròpia.',body:'<div class="teacher-timeline"><article><b>0–25 · Activació</b><p>Repte llampec i microteoria de les cinc accions.</p><em>Separa fets, preguntes i suposicions.</em></article><article><b>25–65 · Tres mirades</b><p>Perspectives, opcions i deduccions amb tres casos.</p><em>Exigeix una dada per justificar cada decisió.</em></article><article><b>65–105 · Fàbrica</b><p>Creació d’una regla de classificació i prova amb el cas frontera.</p><em>La regla ha de funcionar sense explicació oral.</em></article><article><b>105–150 · Cadena</b><p>Descomposició, dependències, paral·lelisme i incidència.</p><em>No tot ha de formar una única seqüència.</em></article><article><b>150–165 · Sortida</b><p>Reflexió individual i recollida d’evidències.</p><em>Comprova que cadascú explica una decisió pròpia.</em></article></div>',footer:'Per a les intervencions literals, pistes graduades i plans alternatius, obre la guia docent.'},
 'aea1-solutions':{tag:'SOLUCIONS I VARIANTS',title:'No hi ha una única resposta, però sí condicions de qualitat',intro:'La guia docent incorpora models complets per a les perspectives, la fàbrica de classificació, el cas frontera i la cadena de dependències.',body:'<div class="teacher-callout"><b>Criteri comú</b><p>Accepta una alternativa quan l’equip explicita la regla, l’aplica de manera consistent i pot comprovar-ne el resultat. Una opinió sense dada no és una justificació.</p></div><div class="teacher-downloads"><a href="downloads/AEA1_S1_Guia_docent.pdf" download><b>Guia docent amb solucionari</b><span>Models, variants i pistes graduades · PDF ↓</span></a></div>',footer:'Sí: «AEA1 S1 — Desmuntem el problema — Guia docent operativa» és el document que conté el solucionari d’aquesta sessió.'},
 'aea1-assessment':{tag:'AVALUACIÓ FORMATIVA',title:'Evidències observables sense saturar',intro:'Aquesta sessió alimenta l’avaluació de l’RA1, però no cal posar una nota independent a cada repte.',body:'<div class="teacher-summary"><article><b>Fitxa 1</b><span>Perspectives, opcions i deduccions justificades.</span></article><article><b>Fitxa 2</b><span>Regla reproduïble i millora després del cas frontera.</span></article><article><b>Fitxa 3</b><span>Descomposició, dependències i adaptació.</span></article><article><b>Sortida</b><span>Comprensió i aportació individual.</span></article></div>',footer:'Registra una fortalesa, una dificultat prioritària i la següent acció de millora; evita corregir tots els detalls alhora.'},
 'aea1-materials':{tag:'MATERIALS DISPONIBLES',title:'Documents sincronitzats de la sessió 1',intro:'La resta de sessions apareixen planificades, però només aquesta disposa encara del paquet complet.',body:'<div class="teacher-downloads"><a href="downloads/AEA1_S1_Guia_docent.pdf" download><b>Guia docent</b><span>Conducció i solucionari · PDF ↓</span></a><a href="downloads/AEA1_S1_Presentacio_visual.pptx" download><b>Presentació visual</b><span>26 diapositives editables · PPTX ↓</span></a><a href="downloads/AEA1_S1_Guia_alumnat.pdf" download><b>Guia de l’alumnat</b><span>11 pàgines · PDF ↓</span></a><a href="downloads/AEA1_Document_mestre.pdf" download><b>Document mestre AEA1</b><span>Planificació de les 12 hores · PDF ↓</span></a></div>',footer:'Les sessions 2–4 s’activaran aquí quan disposin de guia d’alumnat, guia docent i materials revisats.'}
};

function showTeacherGuide(key){const d=teacherGuides[key];if(!d)return;const target=document.querySelector(`#${key.startsWith('aea0')?'aea0':'aea1'}TeacherContent`);target.innerHTML=`<p class="teacher-kicker">${d.tag}</p><h3>${d.title}</h3><p class="teacher-intro">${d.intro}</p>${d.body}<footer>${d.footer}</footer>`;document.querySelectorAll('[data-teacher-detail]').forEach(b=>b.classList.toggle('selected',b.dataset.teacherDetail===key))}
document.querySelectorAll('[data-teacher-aea]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.teacherAea;document.querySelectorAll('[data-teacher-aea]').forEach(b=>b.classList.toggle('selected',b===button));document.querySelectorAll('[data-teacher-view]').forEach(view=>{const active=view.dataset.teacherView===key;view.hidden=!active;view.classList.toggle('selected',active)})}));
document.querySelectorAll('[data-teacher-detail]').forEach(button=>button.addEventListener('click',()=>showTeacherGuide(button.dataset.teacherDetail)));
showTeacherGuide('aea0-overview');showTeacherGuide('aea1-overview');

const s1Tabs={
 start:{tag:'COMENÇA AQUÍ',title:'La missió d’avui',meta:['165 minuts','Equips de 4–6','RA1'],intro:'Aprendre a entendre un problema abans d’actuar: mirar-lo des de més d’un punt de vista, separar-lo en parts i conservar només la informació útil.',steps:['Escriu el nom, el grup, l’equip i el rol inicial a la guia.','Recorda la norma principal: primer prediem; després manipulem.','Durant la sessió registra el procés, no només la resposta final.','Canvia de rol en cada repte perquè tothom analitzi, comprovi i expliqui.'],deliver:'Lliuraràs les Fitxes 1, 2 i 3 i un bitllet de sortida individual.',success:'Una bona solució es pot explicar, provar i millorar.'},
 theory:{tag:'IDEES CLAU · 15 MIN',title:'Cinc accions per pensar millor',meta:['Microteoria','Exemple guiat'],intro:'El pensament computacional no és “pensar com una màquina”, sinó fer visible com resols un problema.',steps:['Mirar: qui veu el problema d’una manera diferent?','Descompondre: quines parts petites puc resoldre o comprovar?','Trobar patrons: què es repeteix o s’assembla?','Abstraure: quines dades són útils i quines distreuen?','Ordenar: quin pas va abans i de què depèn el següent?'],extra:'<div class="machine-example"><b>Exemple: la impressora no imprimeix</b><p>Separem document, cua, connexió i impressora. Comencem per una comprovació ràpida, reversible i amb poc risc.</p></div>',deliver:'No cal memoritzar les cinc paraules: utilitza-les per justificar les decisions.',success:'Pots passar de «no funciona» a una primera prova concreta.'},
 activation:{tag:'ACTIVACIÓ · 10 MIN',title:'Tres històries, un incident',meta:['3 min individual','7 min en equip','Resposta breu'],intro:'Sis ordinadors no poden obrir cap pàgina web. Una alumna, el professor i una tècnica descriuen el mateix incident de manera diferent.',steps:['Subratlla una dada diferent de cada testimoni.','Escriu què considera “el problema” cadascuna de les tres persones.','Proposa dues explicacions possibles, sense decidir encara quina és correcta.','Anota una dada que falta i que ajudaria a decidir.','Compareu i redacteu una conclusió de dues frases.'],extra:'<div class="case-grid"><article><b>Alumna</b>«Internet no funciona i perdrem tota la classe».</article><article><b>Professor</b>«Fallen alguns equips de la mateixa zona».</article><article><b>Tècnica</b>«Necessito saber quins equips fallen i què comparteixen».</article></div>',hint:'Pensa què és un fet observable i què és una interpretació.',deliver:'Resposta individual i conclusió de l’equip.',success:'Formules una pregunta útil abans de tocar cap configuració.'},
 cards:{tag:'FITXA 1 · 30 MIN',title:'Targetes de reptes',meta:['Equip amb rols','3 casos','Una graella'],intro:'Canvieu de perspectiva, proposeu opcions diferents i deduïu què podria passar amb cadascuna.',steps:['Escriviu dues perspectives: qui viu el problema i què necessita?','Separeu els fets comprovats de les interpretacions.','Proposeu dues opcions realment diferents.','Deduïu una conseqüència probable de cada opció.','Trieu l’opció inicial i justifiqueu-la amb una dada.'],extra:'<div class="case-grid"><article><b>A · Aula</b>Només els sis ordinadors de dues taules han perdut la connexió.</article><article><b>B · Arxius</b>Hi ha 240 fitxers sense ordenar i cal trobar una factura en menys d’un minut.</article><article><b>C · Impressió</b>Vint alumnes han d’imprimir una pàgina i només hi ha una impressora.</article></div>',hint:'Utilitza el format: «Si fem…, probablement…».',deliver:'Fitxa 1: perspectives, dues opcions, conseqüències i decisió.',success:'La decisió està justificada amb una dada, no només amb una preferència.'},
 factory:{tag:'FITXA 2 · 35 MIN',title:'Fàbrica de classificació',meta:['12 comandes','3 nivells','Regla v1 i v2'],intro:'Creeu una regla perquè una persona nova sàpiga què atendre primer. Ha de funcionar sense explicacions orals.',steps:['Decidiu quines dades són útils: impacte, urgència i abast.','Escriviu una regla v1 que qualsevol persona pugui aplicar.','Classifiqueu els casos A–L i marqueu els dubtes.','Apliqueu-la al cas M: impacte alt, urgència baixa i tot el centre.','Modifiqueu només la part de la regla que provoca el dubte.'],extra:'<div class="machine-example"><b>No és una regla</b><p>«Ho decidirem segons el cas» no indica quina dada s’ha de mirar ni què cal fer amb ella.</p></div>',hint:'Comença establint què passa quan la urgència és alta. Després resol els empats amb l’impacte o l’abast.',deliver:'Regla v1, classificació, prova del cas M i regla v2.',success:'Dues persones diferents obtenen el mateix resultat aplicant la regla.'},
 chain:{tag:'FITXA 3 · 40 MIN',title:'Descomposició en cadena',meta:['16 targetes','Mapa de dependències','Defensa de 30 s'],intro:'Cal deixar preparats 12 llocs per fer una pràctica de xarxa: equips, cables, instruccions i comprovació final.',steps:['Agrupeu les targetes A–P en 4–6 blocs amb un nom curt.','Ordeneu les tasques dins de cada bloc.','Dibuixeu fletxes només quan una tasca depèn realment d’una altra.','Marqueu dues tasques que es poden fer alhora.','Dos cables fallen: reorganitzeu el pla sense començar de zero.','Prepareu una explicació de 30 segons.'],extra:'<div class="machine-example"><b>Recorda</b><p>No tot és una cadena. Comptar equips, reunir cables i obrir la guia poden començar en paral·lel si no depenen entre si.</p></div>',hint:'Prova aquests blocs inicials: preparar, distribuir, comprovar i tancar.',deliver:'Mapa amb totes les targetes, dependències i canvi pels cables defectuosos.',success:'L’ordre es pot seguir i la incidència no obliga a refer tot el pla.'},
 exit:{tag:'TANCAMENT · 15 MIN',title:'Bitllet de sortida individual',meta:['Sense copiar','5 respostes','Abans de marxar'],intro:'Explica amb frases pròpies què has fet i com ha canviat el vostre pla. Aquesta part és individual.',steps:['Descompondre: quina part del repte final has separat o reorganitzat?','Abstraure: quina dada has considerat irrellevant?','Decidir: quines dues opcions heu comparat i per què n’heu triat una?','Treball en equip: quina aportació observable has fet?','Autorevisa que has justificat una decisió i registrat un error o millora.'],deliver:'Fitxes 1–3 llegibles, bitllet individual amb nom i totes les targetes retornades.',success:'Pots completar la frase «Avui he après que abans d’actuar convé…».'}
};
function showS1(key){const d=s1Tabs[key],extra=d.extra||'',hint=d.hint?`<button class="hint-button" type="button">Mostra una pista</button><div class="hint">${d.hint}</div>`:'';document.querySelector('#s1Content').innerHTML=`<div class="stage-head"><div><p class="overline">${d.tag}</p><h3>${d.title}</h3></div></div><div class="stage-meta">${d.meta.map(x=>`<span>${x}</span>`).join('')}</div><p class="instruction">${d.intro}</p>${extra}<ol class="step-list">${d.steps.map(x=>`<li>${x}</li>`).join('')}</ol>${hint}<div class="lesson-boxes"><div class="lesson-box"><b>Què has de produir?</b><span>${d.deliver}</span></div><div class="lesson-box success"><b>Criteri d’èxit</b><span>${d.success}</span></div></div>`;document.querySelectorAll('[data-s1-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.s1Tab===key));const hb=document.querySelector('.hint-button');if(hb)hb.addEventListener('click',()=>{const h=document.querySelector('.hint');h.classList.toggle('visible');hb.textContent=h.classList.contains('visible')?'Amaga la pista':'Mostra una pista'})}
document.querySelectorAll('[data-s1-tab]').forEach(b=>b.addEventListener('click',()=>{showS1(b.dataset.s1Tab);document.querySelector('#s1Content').focus()}));showS1('start');

const s2Tabs={
 start:{tag:'MISSIÓ · 10 MIN',title:'Fes que una altra persona entengui exactament què vols',meta:['165 minuts','Parelles + equips de 4','Sense ordinador obligatori'],intro:'Avui una persona farà de programadora i una altra de processador. El processador no interpreta intencions: executa literalment les ordres que rep.',extra:'<div class="teacher-callout"><b>Pregunta guia</b><p>Si una instrucció només funciona perquè l’altra persona “ja sap què volies dir”, és prou precisa?</p></div>',steps:['Forma una parella i decidiu qui començarà com a programador/a i qui com a processador/a.','Prepareu la guia, un llapis i les targetes d’ordres.','A cada repte, primer escriviu o seleccioneu les ordres; després executeu-les sense corregir sobre la marxa.','Registreu la primera diferència entre el resultat esperat i el resultat real.','Canvieu els rols abans del repte següent.'],deliver:'Al final lliuraràs una única guia amb els quatre registres i una resposta individual.',success:'Pots escriure una instrucció que una altra persona executa sense haver de preguntar-te res.'},
 literal:{tag:'REPTE 1 · 20 MIN',title:'El robot literal',meta:['Parelles','Dibuix ocult','Primera versió sense preguntes'],intro:'La persona programadora veu una figura de 5 × 5 caselles. Ha de conduir el llapis de la seva parella sense ensenyar-li el model ni fer gestos.',extra:'<div class="pixel-model"><div><span></span><span class="on"></span><span class="on"></span><span class="on"></span><span></span><span></span><span class="on"></span><span></span><span class="on"></span><span></span><span class="on"></span><span class="on"></span><span class="on"></span><span class="on"></span><span class="on"></span><span class="on"></span><span></span><span class="on"></span><span></span><span class="on"></span><span class="on"></span><span></span><span></span><span></span><span class="on"></span></div><p>Model A · només el veu qui programa</p></div>',steps:['Situa el llapis: fila 1, columna 1.','Escriu les ordres abans de començar. No pots dir «aquí», «així» ni «una mica».','La persona processadora executa les ordres literalment i no pot fer preguntes.','Compareu el dibuix obtingut amb el model. Marqueu la primera instrucció ambigua.','Reescriviu només les ordres necessàries i repetiu la prova canviant els rols.'],hint:'Utilitza coordenades o ordres constants: fila, columna, pinta, mou una casella.',deliver:'Dibuix de la primera execució + una instrucció ambigua + versió corregida.',success:'La segona execució produeix el mateix patró sense gestos ni explicacions addicionals.'},
 compiler:{tag:'REPTE 2 · 25 MIN',title:'Compila instruccions humanes',meta:['Equip de 4','8 ordres defectuoses','Precisió abans que brevetat'],intro:'Transformeu frases que una persona interpreta fàcilment en ordres que es puguin executar i comprovar.',extra:'<div class="bug-board"><span>«Posa-ho bé»</span><span>«Ves cap allà»</span><span>«Repeteix unes vegades»</span><span>«Ordena ràpidament»</span><span>«Agafa el següent»</span><span>«Si cal, para»</span><span>«Fes el mateix»</span><span>«Acaba quan estigui»</span></div>',steps:['Per a cada frase, subratlleu la paraula que provoca el dubte.','Escriviu quina dada falta: objecte, posició, quantitat, condició o criteri de finalització.','Reescriviu quatre frases amb un verb d’acció i dades observables.','Intercanvieu-les amb un altre equip, que les intentarà executar o representar.','Corregiu només les frases que han generat preguntes diferents.'],hint:'Una ordre verificable permet respondre sí/no a «ja està feta?».',deliver:'Taula amb 4 frases: original → dada que falta → instrucció compilada → prova.',success:'Un altre equip interpreta les quatre instruccions de la mateixa manera.'},
 cpu:{tag:'REPTE 3 · 35 MIN',title:'CPU humana: prepara un lloc de treball',meta:['Equip de 4','Rols rotatius','Condicions i comprovació'],intro:'Programeu una persona perquè prepari un lloc de treball amb una safata, tres targetes numerades, un llapis i un full. Només pot usar les ordres permeses.',extra:'<div class="command-palette"><code>AGAFAR [objecte]</code><code>DEIXAR [objecte] A [posició]</code><code>GIRAR [objecte]</code><code>REPETIR [n] VEGADES</code><code>SI [condició], [acció]</code><code>COMPROVAR [criteri]</code></div>',steps:['Definiu l’estat final amb una llista de comprovació de quatre punts.','Escriviu una primera seqüència amb les ordres permeses.','La CPU executa sense ajudar ni corregir el programa. La persona observadora fa una traça: pas, ordre i resultat.','Si falla, atureu-vos a la primera divergència i modifiqueu una sola ordre.','Repetiu la seqüència completa i marqueu la comprovació final.'],hint:'Primer descriu l’estat final: què hi ha, on és i com sabràs que està correcte.',deliver:'Algorisme v1 + traça d’execució + correcció v2 + checklist final.',success:'Una CPU nova pot preparar el lloc correctament seguint només la versió v2.'},
 blocks:{tag:'REPTE 4 · 30 MIN',title:'Converteix repeticions en blocs',meta:['Equip','Tasques reutilitzables','CE 1.5'],intro:'Un bon programa no torna a escriure la mateixa seqüència cada vegada. Identifiqueu un grup d’ordres repetit i doneu-li un nom que expliqui què aconsegueix.',extra:'<div class="reuse-demo"><pre><code>AGAFAR targeta 1\nDEIXAR targeta 1 A safata\nAGAFAR targeta 2\nDEIXAR targeta 2 A safata\nAGAFAR targeta 3\nDEIXAR targeta 3 A safata</code></pre><div>→</div><pre><code>BLOC col·loca_targeta(n)\n  AGAFAR targeta n\n  DEIXAR targeta n A safata\n\nREPETIR per a 1, 2 i 3:\n  col·loca_targeta(n)</code></pre></div>',steps:['Encercleu dues o més seqüències que fan la mateixa funció.','Poseu al bloc un nom format per verb + objectiu.','Indiqueu quina dada canvia cada vegada: serà el paràmetre.','Substituïu les repeticions per crides al bloc.','Expliqueu un segon context en què el bloc també seria útil.'],hint:'El nom ha d’explicar el resultat, no la forma visual de les ordres.',deliver:'Seqüència original marcada + definició d’un bloc + versió reutilitzable + segon ús.',success:'El bloc evita repeticions i es pot utilitzar canviant només una dada.'},
 final:{tag:'REPTE FINAL · 30 MIN',title:'Programa la ruta de missatgeria',meta:['Individual → parella','Mapa 6 × 6','Obstacles i comprovació'],intro:'Escriu un algorisme perquè un missatger surti de la base, reculli dos paquets i arribi al punt de lliurament sense travessar obstacles.',extra:'<div class="route-map" aria-label="Mapa de sis files i sis columnes"><span class="start">S</span><span></span><span class="wall">■</span><span></span><span class="pack">P</span><span></span><span></span><span></span><span class="wall">■</span><span></span><span></span><span></span><span class="pack">P</span><span></span><span></span><span></span><span class="wall">■</span><span></span><span></span><span class="wall">■</span><span></span><span></span><span></span><span></span><span></span><span></span><span></span><span class="wall">■</span><span></span><span></span><span></span><span></span><span></span><span></span><span></span><span class="goal">F</span></div>',steps:['Defineix les ordres que utilitzaràs: AVANÇA, GIRA, RECULL i ENTREGA.','Escriu la ruta completa sense moure cap fitxa.','Una parella executa literalment i registra la primera divergència.','Corregeix l’algorisme i agrupa en un bloc qualsevol moviment repetit.','Afegeix una comprovació abans d’entregar.'],hint:'Numera files i columnes abans de començar. Una ruta correcta no ha de ser necessàriament l’única.',deliver:'Ruta v1, traça de la parella, ruta final amb un bloc i comprovació.',success:'La ruta recull els dos paquets, evita els obstacles i acaba a F amb una comprovació explícita.'},
 deliver:{tag:'TANCAMENT · 15 MIN',title:'Un únic lliurable fàcil de revisar',meta:['Individual','PDF o paper','Nom clar'],intro:'No cal crear documents separats per a cada repte. Completa la guia de treball i entrega-la com una única evidència.',extra:'<div class="delivery-choice"><article><b>Opció digital</b><span>Completa el document, exporta’l a PDF i entrega <code>AEA1_S2_Cognom_Nom.pdf</code>.</span></article><article><b>Opció paper</b><span>Entrega la guia grapada, amb nom a totes les pàgines i fotografies només si ho demana el docent.</span></article></div>',steps:['Comprova que hi ha una primera versió i una correcció als reptes 1 i 3.','Revisa que el bloc reutilitzable té un nom clar i un paràmetre.','Completa la ruta final i la seva comprovació.','Respon individualment: «La instrucció que més he hagut de precisar ha estat… perquè…».','Entrega només el document final pel canal indicat pel professorat.'],deliver:'AEA1_S2_Cognom_Nom.pdf o guia en paper, segons indiqui el docent.',success:'El document permet reconstruir què vas intentar, què va fallar i com ho vas millorar.'}
};
function showS2(key){const d=s2Tabs[key],extra=d.extra||'',hint=d.hint?`<button class="hint-button" type="button">Mostra una pista</button><div class="hint">${d.hint}</div>`:'';document.querySelector('#s2Content').innerHTML=`<div class="stage-head"><div><p class="overline">${d.tag}</p><h3>${d.title}</h3></div></div><div class="stage-meta">${d.meta.map(x=>`<span>${x}</span>`).join('')}</div><p class="instruction">${d.intro}</p>${extra}<ol class="step-list">${d.steps.map(x=>`<li>${x}</li>`).join('')}</ol>${hint}<div class="lesson-boxes"><div class="lesson-box"><b>Què has de produir?</b><span>${d.deliver}</span></div><div class="lesson-box success"><b>Criteri d’èxit</b><span>${d.success}</span></div></div>`;document.querySelectorAll('[data-s2-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.s2Tab===key));const hb=document.querySelector('#s2Content .hint-button');if(hb)hb.addEventListener('click',()=>{const h=document.querySelector('#s2Content .hint');h.classList.toggle('visible');hb.textContent=h.classList.contains('visible')?'Amaga la pista':'Mostra una pista'})}
document.querySelectorAll('[data-s2-tab]').forEach(b=>b.addEventListener('click',()=>{showS2(b.dataset.s2Tab);document.querySelector('#s2Content').focus()}));showS2('start');

Object.assign(teacherGuides,{
 'aea1-s2-overview':{tag:'VISIÓ RÀPIDA · SESSIÓ 2',title:'Programem persones',intro:'Sessió desconnectada per transformar llenguatge quotidià en instruccions precises, executables, comprovables i reutilitzables.',body:'<div class="teacher-summary"><article><b>Durada</b><span>165 minuts</span></article><article><b>Agrupament</b><span>Parelles, equips de 4 i final individual</span></article><article><b>Lliurable</b><span>Una guia única en PDF o paper</span></article><article><b>CE principals</b><span>1.4, 1.5, 1.6 i 1.7</span></article></div><div class="teacher-callout"><b>Idea central</b><p>No s’avalua qui dona instruccions més ràpid, sinó qui aconsegueix que una altra persona les executi sense interpretar intencions.</p></div>',footer:'Reforça també iniciativa, autonomia, responsabilitat i relacions professionals: CE 1.8–1.11.'},
 'aea1-s2-run':{tag:'CONDUCCIÓ · 165 MIN',title:'Guió operatiu de la sessió 2',intro:'Alterna execució, observació i millora. No permetis corregir oralment una ordre mentre s’executa: l’error ha de quedar visible i registrat.',body:'<div class="teacher-timeline"><article><b>0–10 · Missió</b><p>Explica programador, processador i execució literal. Modela una ordre ambigua.</p><em>Pregunta: «Quina dada falta?»</em></article><article><b>10–30 · Robot literal</b><p>Parelles amb model ocult. Primera execució sense preguntes; segona després de corregir.</p><em>No valoris el dibuix: valora la precisió.</em></article><article><b>30–55 · Compilador</b><p>Transformen quatre frases vagues en instruccions observables i les proven amb un altre equip.</p><em>Classifica el dubte: objecte, posició, quantitat, condició o final.</em></article><article><b>55–90 · CPU humana</b><p>Defineixen l’estat final, executen una seqüència i fan una traça pas a pas.</p><em>Atura la revisió a la primera divergència.</em></article><article><b>90–120 · Blocs</b><p>Detecten repeticions, creen un bloc amb paràmetre i expliquen un segon ús.</p><em>Relaciona-ho explícitament amb CE 1.5.</em></article><article><b>120–150 · Ruta final</b><p>Treball individual i prova per parelles amb mapa, obstacles i dos paquets.</p><em>Accepta rutes diferents si compleixen totes les condicions.</em></article><article><b>150–165 · Lliurament</b><p>Checklist, reflexió individual i entrega d’una única guia.</p><em>No demanis documents duplicats.</em></article></div>',footer:'Pausa flexible: es pot inserir després de la CPU humana o abans del repte final.'},
 'aea1-s2-solutions':{tag:'SOLUCIONS I CRITERIS',title:'Models per comprovar, no per imposar una única resposta',intro:'Els reptes admeten variants. Una solució és vàlida quan les ordres són completes, tenen un criteri de finalització i una altra persona obté el resultat previst.',body:'<div class="solution-grid"><section><h4>Robot literal</h4><p>Model recomanat: «Situa’t a fila 1, columna 2; pinta les caselles…». No acceptis «fes una forma com aquesta» ni indicacions gestuals.</p></section><section><h4>Compilador</h4><p>«Repeteix unes vegades» → «Repeteix 3 vegades». «Acaba quan estigui» → «Acaba quan les tres targetes siguin dins la safata i ordenades de l’1 al 3».</p></section><section><h4>CPU humana</h4><p>La seqüència ha d’anomenar objecte i posició. La comprovació final ha de descriure quatre condicions observables.</p></section><section><h4>Blocs</h4><p>Model: <code>col·loca_targeta(n)</code>. El paràmetre és el número; el segon ús pot ser una altra safata o una sèrie diferent.</p></section></div><div class="teacher-callout"><b>Ruta final</b><p>No hi ha una ruta única. Verifica en aquest ordre: surt de S, recull els dos P, no passa per ■, acaba a F, inclou ENTREGA i una comprovació.</p></div>',footer:'Si una ruta és més llarga però correcta, no és un error. L’optimització només es comenta després de garantir la correcció.'},
 'aea1-s2-assessment':{tag:'AVALUACIÓ FORMATIVA',title:'Pauta breu sobre 10 punts',intro:'Corregeix el procés visible i la capacitat de millora, no només el resultat final.',body:'<div class="quick-rubric"><article><b>2 punts · Precisió</b><span>Ordres sense referències vagues.</span></article><article><b>2 punts · Execució</b><span>Traça fidel i primera divergència identificada.</span></article><article><b>2 punts · Millora</b><span>Canvi concret entre v1 i v2.</span></article><article><b>2 punts · Reutilització</b><span>Bloc ben anomenat amb paràmetre i segon ús.</span></article><article><b>2 punts · Documentació</b><span>Guia completa, clara i reflexió pròpia.</span></article></div><div class="ce-map"><h4>Correspondència principal</h4><p><b>1.4:</b> ordre d’execució i traça. <b>1.5:</b> bloc reutilitzable. <b>1.6:</b> registre de versions i comprovació. <b>1.7:</b> consulta de la paleta i selecció d’ajudes.</p><p><b>Transversals:</b> 1.8, 1.9, 1.10 i 1.11 durant els rols, la prova entre iguals i la revisió individual.</p></div>',footer:'Feedback recomanat: una ordre ben escrita + la primera ambigüitat prioritària + una proposta concreta de reescriptura.'},
 'aea1-s2-materials':{tag:'MATERIALS DE LA SESSIÓ 2',title:'Tot preparat per impartir-la',intro:'Pots treballar directament des de la web o repartir les guies en paper. No cal ordinador, excepte si l’alumnat completa digitalment el lliurable.',body:'<div class="teacher-downloads"><a href="#aea1-s2"><b>Vista interactiva de l’alumnat</b><span>Obre la sessió 2 →</span></a><a href="downloads/AEA1_S2_Guia_alumnat.pdf" download><b>Guia de treball</b><span>Activitats i evidències · PDF ↓</span></a><a href="downloads/AEA1_S2_Guia_docent.pdf" download><b>Guia docent</b><span>Conducció, respostes i rúbrica · PDF ↓</span></a></div>',footer:'Prepara una còpia de la guia per alumne, una quadrícula i targetes per parella, i una safata o espai delimitat per equip.'}
});

document.querySelectorAll('[data-teacher-session]').forEach(button=>button.addEventListener('click',()=>{const session=button.dataset.teacherSession;document.querySelectorAll('[data-teacher-session]').forEach(b=>b.classList.toggle('selected',b===button));const isS2=session==='aea1-s2';const keys=isS2?['aea1-s2-overview','aea1-s2-run','aea1-s2-solutions','aea1-s2-assessment','aea1-s2-materials']:['aea1-overview','aea1-run','aea1-solutions','aea1-assessment','aea1-materials'];document.querySelectorAll('#aea1TeacherTabs [data-teacher-detail]').forEach((tab,i)=>{tab.dataset.teacherDetail=keys[i]});document.querySelector('#aea1-teacher-title').textContent=isS2?'Programem persones · guia docent':'Laboratori de pensament · guia docent';showTeacherGuide(keys[0])}));

// AEA1 definitiva: quatre sessions vivencials amb la mateixa rutina.
const aea1Hybrid={
 s1:{title:'La màquina que no pensa',label:'SESSIÓ 1 · 165 MIN',phases:{
  mission:{tag:'MISSIÓ · 10 MIN',title:'Pots donar una ordre que no necessiti interpretació?',meta:['Equips de 4','Material de taula','Tancament individual'],intro:'Construireu una màquina humana. Una persona dona ordres, una altra les executa literalment i dues observen què passa.',steps:['Repartiu els rols: programador/a, màquina, observador/a i relator/a.','Llegiu només l’objectiu; encara no busqueu la millor solució.','Quan una ordre sigui ambigua, la màquina tria una interpretació possible.','No corregiu oralment: registreu la primera diferència.'],deliver:'Una ordre inicial i la primera ambigüitat detectada.',success:'Podeu explicar per què dues persones han entès coses diferents.'},
  activate:{tag:'ACTIVA’T · 20 MIN',title:'Tres reptes, no quaranta',meta:['S1 · S2 · S3','5 minuts cadascun','Resposta breu'],intro:'El docent us donarà tres targetes del banc. Són una activació, no un examen.',steps:['Pensa 60 segons en silenci.','Contrasta una resposta amb la parella.','L’equip tria una resposta i n’explica el criteri.','Si acabeu, demaneu P8 com a ampliació.'],deliver:'Una justificació oral per targeta.',success:'La resposta inclou una dada o regla, no només una opinió.'},
  workshop:{tag:'TALLER CENTRAL · 60 MIN',title:'Programa una persona real',meta:['Ordres literals','Dues execucions','Una sola correcció cada vegada'],intro:'Prepareu una tasca senzilla amb targetes i objectes. La màquina només pot executar les ordres escrites.',steps:['Descriviu l’estat final observable.','Escriviu de 5 a 8 ordres.','Executeu-les sense donar pistes ni fer gestos.','Atureu-vos a la primera divergència.','Canvieu una ordre i repetiu des del principi.','Dividiu la missió en 4–6 parts amb noms curts.'],deliver:'Seqüència v1, primera divergència i versió corregida.',success:'Un nou executor obté el resultat sense preguntar res.'},
  idea:{tag:'IDEA CLAU · 20 MIN',title:'Primer vius el problema; després li posem nom',meta:['Abstracció','Descomposició','Comprovació'],intro:'Abstraure és quedar-se amb la informació útil. Descompondre és separar un problema en parts manejables. Comprovar és comparar el resultat real amb el previst.',steps:['Assenyaleu una dada imprescindible.','Assenyaleu un detall que podíeu ignorar.','Poseu nom a cada part de la missió.','Definiu una comprovació que es respongui amb sí o no.'],deliver:'Tres conceptes vinculats al que acaba de passar.',success:'Podeu donar un exemple vostre de cada concepte.'},
  apply:{tag:'APLICA · 40 MIN',title:'Canvia de context sense començar de zero',meta:['Equip','Targeta nova','Mateixa estratègia'],intro:'Resoleu una targeta nova reutilitzant el procés del taller: objectiu, dades, parts, ordre i comprovació.',steps:['Escriviu què ha de quedar resolt.','Separeu fets de suposicions.','Dividiu el repte en parts.','Ordeneu només les parts que tenen dependència.','Comproveu la proposta amb un cas.'],deliver:'Mapa breu del problema al quadern.',success:'La solució es pot seguir sense una explicació extra.'},
  close:{tag:'TANCA · 15 MIN',title:'Una evidència pròpia',meta:['Individual','3 frases','Amb nom'],intro:'No copiis la resposta de l’equip. Explica què has entès tu.',steps:['Completa: «Abans d’actuar convé…».','Escriu una ordre que hagis hagut de precisar.','Descriu la teva aportació observable a l’equip.'],deliver:'Tancament individual de la sessió 1.',success:'Les tres respostes són concretes i fan referència al taller.'}}},
 s2:{title:'L’autòmat al laberint',label:'SESSIÓ 2 · 165 MIN',phases:{
  mission:{tag:'MISSIÓ · 10 MIN',title:'Arriba a la meta amb un programa que es pugui provar',meta:['Tauler A3','Fitxa autòmat','Sense cinta al terra'],intro:'Programareu una fitxa damunt la taula. Primer buscareu una ruta correcta; després haureu de fer-la més clara amb només 12 targetes.',steps:['Situeu inici, meta i obstacles.','Trieu executor/a, programador/a, depurador/a i relator/a.','No moveu la fitxa mentre prepareu el programa.','Prediu on acabarà abans d’executar.'],deliver:'Predicció i primera seqüència.',success:'Tothom coneix les ordres abans de començar.'},
  activate:{tag:'ACTIVA’T · 15 MIN',title:'Escalfa amb S4, S5 i L2',meta:['3 targetes','Resposta ràpida','L3 opcional'],intro:'Busqueu patrons, passos i errors. No cal escriure explicacions llargues.',steps:['Resol individualment el primer minut.','Contrasta amb l’equip.','Marca quina regla has utilitzat.'],deliver:'Una regla breu per repte.',success:'La regla permet comprovar la resposta.'},
  workshop:{tag:'TALLER CENTRAL · 75 MIN',title:'Dues rondes, un descobriment',meta:['Ronda 1 lliure','Ronda 2: 12 targetes','Execució literal'],intro:'La primera ronda prioritza que funcioni. La segona us obliga a detectar repeticions i crear blocs.',steps:['Ronda 1: escriviu i executeu la ruta completa.','Feu una traça i marqueu la primera divergència.','Corregiu una única ordre i repetiu.','Ronda 2: resolgueu una ruta nova amb un màxim de 12 targetes.','Agrupeu un patró repetit i poseu-li un nom.'],deliver:'Ruta v1, traça, correcció i bloc reutilitzable.',success:'La fitxa arriba a la meta i el bloc es pot tornar a usar.'},
  idea:{tag:'IDEA CLAU · 20 MIN',title:'Un error és informació',meta:['Seqüència','Traça','Depuració','Bloc'],intro:'La traça mostra l’estat després de cada ordre. Depurar és localitzar la primera diferència, modificar una causa i tornar a provar.',steps:['Distingiu error de resultat i error de procés.','Expliqueu per què corregim la primera divergència.','Identifiqueu què canvia i què es manté dins del bloc.'],deliver:'Definició pròpia de traça i depuració.',success:'Podeu reconstruir com s’ha produït l’error.'},
  apply:{tag:'APLICA · 30 MIN',title:'Intercanvia el programa',meta:['Un altre equip','Sense explicació oral','Validació'],intro:'Doneu el vostre programa a un altre equip. Només pot llegir-lo i executar-lo.',steps:['Entregueu programa i tauler.','Observeu en silenci.','Registreu la primera pregunta o divergència.','Feu una correcció i una nova prova.'],deliver:'Programa validat per un altre equip.',success:'La segona execució arriba a la meta sense aclariments.'},
  close:{tag:'TANCA · 15 MIN',title:'Què ha millorat?',meta:['Individual','Quadern','15 minuts'],intro:'Explica el canvi que ha convertit una ruta en un programa més clar.',steps:['Completa la frase del quadern.','Dibuixa un bloc i indica quin element varia.','Assenyala com has comprovat el resultat.'],deliver:'Tancament individual de la sessió 2.',success:'Relaciona un canvi concret amb el resultat observat.'}}},
 s3:{title:'Transmissió de sprite',label:'SESSIÓ 3 · 165 MIN',phases:{
  mission:{tag:'MISSIÓ · 10 MIN',title:'Envia una imatge sense ensenyar-la',meta:['Parelles','Sprite 16 × 16','Esquena amb esquena'],intro:'Una persona veu el sprite i l’altra el reconstrueix només a partir d’un missatge codificat.',steps:['No mostreu el model.','Acordeu un alfabet i una regla.','Feu una prova amb dues files.','Només després transmeteu el sprite complet.'],deliver:'Regla de codificació compartida.',success:'Una tercera persona pot interpretar el codi.'},
  activate:{tag:'ACTIVA’T · 15 MIN',title:'Patrons amb P1, P2 i P3',meta:['3 reptes','P4 opcional','Parelles'],intro:'Detecteu què es repeteix i què canvia. Això us ajudarà a inventar un codi més curt.',steps:['Marca patrons consecutius.','Compara dues formes de descriure’ls.','Tria la regla menys ambigua.'],deliver:'Una regla verbal o visual.',success:'La regla prediu el cas següent.'},
  workshop:{tag:'TALLER CENTRAL · 80 MIN',title:'Fidelitat contra economia',meta:['Transmissió 1','Redisseny','Transmissió 2'],intro:'El millor codi no és només curt: també ha de permetre reconstruir la imatge correctament.',steps:['Definiu símbols i ordre de lectura.','Transmeteu sense preguntes obertes.','Compareu els dos sprites casella a casella.','Compteu errors i símbols utilitzats.','Redissenyeu la regla.','Repetiu amb un sprite o fragment nou.'],deliver:'Dues codificacions i comparació d’errors/cost.',success:'La segona versió manté o millora la fidelitat amb una regla més clara.'},
  idea:{tag:'IDEA CLAU · 20 MIN',title:'Representar és decidir què conserves',meta:['Patró','Abstracció','Compressió'],intro:'Codificar és representar informació amb una regla. Comprimir és reduir la representació sense perdre allò necessari per reconstruir-la.',steps:['Identifiqueu la informació imprescindible.','Expliqueu què significa cada símbol.','Distingiu codi curt de codi útil.'],deliver:'Una definició pròpia i un exemple.',success:'Podeu explicar una decisió de disseny del vostre codi.'},
  apply:{tag:'APLICA · 25 MIN',title:'Publica una especificació mínima',meta:['Equip','Una pàgina','Prova externa'],intro:'Escriviu la guia mínima perquè un altre equip utilitzi el vostre sistema.',steps:['Poseu nom al sistema.','Escriviu alfabet, ordre de lectura i separadors.','Incloeu un exemple de dues files.','Demaneu a un altre equip que el descodifiqui.'],deliver:'Especificació d’una pàgina.',success:'Funciona sense que els creadors hagin d’intervenir.'},
  close:{tag:'TANCA · 15 MIN',title:'Què no podies perdre?',meta:['Individual','Resposta breu','Amb evidència'],intro:'Pensa en la diferència entre reduir informació i destruir-la.',steps:['Completa la frase del quadern.','Anota un error de reconstrucció i la seva causa.','Descriu la teva aportació.'],deliver:'Tancament individual de la sessió 3.',success:'Relaciona una decisió del codi amb un resultat visible.'}}},
 s4:{title:'Torneig + Boss',label:'SESSIÓ 4 · 165 MIN',phases:{
  mission:{tag:'MISSIÓ · 10 MIN',title:'Ordena millor i demostra què saps',meta:['Torneig en equip','Boss individual','Segona vida'],intro:'Primer comparareu estratègies per ordenar. Després resoldreu un repte individual que integra tot l’AEA1.',steps:['En el torneig només podeu comparar dues targetes cada vegada.','Compteu totes les comparacions.','Al Boss treballeu individualment.','La segona vida conserva l’error i afegeix la correcció.'],deliver:'Registre del torneig + Boss individual.',success:'Pots justificar una estratègia i corregir un error propi.'},
  activate:{tag:'ACTIVA’T · 15 MIN',title:'L5, L6 i X2',meta:['3 reptes','S8 opcional','Estratègia'],intro:'No busqueu només la resposta: compareu maneres d’arribar-hi.',steps:['Resol una primera versió.','Explica l’ordre de decisions.','Busca un pas innecessari.'],deliver:'Una estratègia explicada.',success:'Pots indicar per què has triat aquest ordre.'},
  workshop:{tag:'TORNEIG · 50 MIN',title:'Ordena amb comparacions limitades',meta:['8 targetes','Només parelles','Compta operacions'],intro:'Cada equip rep vuit valors ocults. Només podeu descobrir quin és més gran comparant una parella.',steps:['Acordeu una estratègia abans de començar.','Registreu cada comparació.','Ordeneu els vuit valors.','Compareu recompte i mètode amb un altre equip.','Redissenyeu l’estratègia i proveu amb una nova sèrie.'],deliver:'Ordre final, nombre de comparacions i estratègia millorada.',success:'L’ordre és correcte i podeu reconstruir totes les decisions.'},
  idea:{tag:'IDEA CLAU · 20 MIN',title:'Correcte primer; eficient després',meta:['Estratègia','Eficiència','Traça'],intro:'Dues solucions poden ser correctes i tenir costos diferents. La traça permet explicar decisions i comprovar resultats.',steps:['Distingiu correcció i eficiència.','Compareu nombre de passos o comparacions.','Expliqueu quan una solució més clara pot ser preferible.'],deliver:'Criteri compartit per comparar estratègies.',success:'No confoneu «més curt» amb «sempre millor».'},
  apply:{tag:'BOSS INDIVIDUAL · 40 MIN',title:'Integra, prova i justifica',meta:['Individual','4 parts','Consulta breu permesa'],intro:'Resoldràs una descomposició, una regla, una traça i una caça del bug.',steps:['Llegeix totes les parts abans de començar.','Mostra els passos, no només el resultat.','Comprova cada resposta amb un cas.','Entrega la primera versió sense esborrar.'],deliver:'Boss individual complet.',success:'El procés escrit permet entendre com has pensat.'},
  close:{tag:'SEGONA VIDA · 30 MIN',title:'Corregir també és demostrar aprenentatge',meta:['Un altre color','Sense esborrar','Fins a 2 punts recuperables'],intro:'Revisa el Boss, corregeix una resposta i explica l’error. No es premia endevinar: es premia entendre el canvi.',steps:['Marca la primera divergència.','Escriu la correcció amb un altre color.','Completa: «El meu error era…».','Completa: «Ara sé que funciona perquè…».'],deliver:'Boss amb primera versió, correcció i justificació.',success:'La correcció està argumentada i es pot comprovar.'}}}
};
const aea1CardRoutes={
 s1:{title:'Pensar abans d’actuar',family:'S',common:'S1 i S2',choice:'tria 4 entre S3 i S10',workshop:'la màquina que no pensa',concept:'perspectives, dades útils i descomposició'},
 s2:{title:'Donar ordres que funcionen',family:'L',common:'L1 i L2',choice:'tria 4 entre L3 i L10',workshop:'l’autòmat al laberint',concept:'lògica, seqüències, traça i depuració'},
 s3:{title:'Codificar sense perdre informació',family:'P',common:'P1 i P2',choice:'tria 4 entre P3 i P10',workshop:'la transmissió de sprite',concept:'patrons, representació i compressió'},
 s4:{title:'Estratègia i repte final',family:'X',common:'X1 i X2',choice:'tria 4 entre X3 i X10',workshop:'el torneig d’ordenació i el Boss',concept:'estratègia, eficiència i autonomia'}
};
Object.entries(aea1CardRoutes).forEach(([key,r])=>{const s=aea1Hybrid[key];s.title=r.title;s.phases.mission={tag:'BRIEFING · 10 MIN',title:`Ruta ${r.family} · sis targetes amb sentit`,meta:['100% desconnectat','2 comunes + 4 a escollir','Un sol passaport'],intro:`Aquesta sessió combina les targetes ${r.family} amb ${r.workshop}. Les targetes no són ampliació: són la meitat del recorregut.`,steps:[`Resol obligatòriament ${r.common}.`,`${r.choice}.`,'No escriguis a les targetes: són reutilitzables.','Al passaport només anotaràs codi, idea clau i comprovació.'],deliver:'Una ruta personal de sis targetes i el material del taller preparat.',success:'Saps quines dues targetes són comunes i quines quatre pots escollir.'};s.phases.activate={tag:'CIRCUIT A · 55 MIN',title:`Primera ronda de targetes ${r.family}`,meta:[r.common,'1 targeta escollida','Individual → parella → equip'],intro:'Comença cada repte en silenci, contrasta una estratègia i valida-la amb una pregunta o un cas de prova.',steps:['Llegeix i reformula què et demana la targeta.','Pensa individualment durant 60–90 segons.','Compara la teva regla o estratègia amb una parella.','L’equip acorda una resposta comprovable.','Registra al passaport només la conclusió final.'],deliver:'Tres targetes resoltes: les dues comunes i una d’elecció.',success:'Cada resposta inclou una regla, una dada o una comprovació.'};s.phases.workshop.tag='TALLER MANIPULATIU · 50 MIN';s.phases.idea={tag:'MICROLLIÇÓ · 15 MIN',title:`Posem nom al que ha passat`,meta:[r.concept,'Exemples del taller','Màxim 15 minuts'],intro:'La teoria parteix dels errors, patrons i decisions que acabeu d’observar; no és una explicació llarga abans de començar.',steps:['Recupera una situació real del taller.','Relaciona-la amb dos conceptes clau.','Escriu una definició amb paraules pròpies.','Afegeix un exemple que no sigui el del professor.'],deliver:'Una idea clau al passaport.',success:'Pots explicar el concepte a partir del que has fet.'};s.phases.apply={tag:'CIRCUIT B · 25 MIN',title:`Segona ronda: elecció i nivell`,meta:['3 targetes escollides','Ritme flexible','Ajuda graduada'],intro:`Completa la teva ruta triant tres targetes més de la família ${r.family}. No cal que tot l’equip faci exactament les mateixes.`,steps:['Tria una targeta que et sembli assequible.','Tria una que et faci dubtar.','Tria una tercera segons el temps disponible.','Demana una pista només després d’escriure un primer intent.','Valida almenys una resposta amb un altre equip.'],deliver:'Tres targetes noves i sis codis totals al passaport.',success:'Has completat sis reptes i pots justificar una elecció.'};s.phases.close={tag:'PASSAPORT · 10 MIN',title:'Registra sense convertir-ho en paperassa',meta:['Individual','6 codis','Una reflexió'],intro:'El passaport és el lliurable. No copiïs enunciats ni redactis sis explicacions llargues.',steps:['Comprova que hi consten sis codis.','Destaca el repte que t’ha fet canviar d’estratègia.','Escriu com has comprovat una resposta.','Completa la frase final de la sessió.'],deliver:'Una pàgina de passaport completada.',success:'El registre permet veure què has resolt i què has après, sense repetir la targeta.'};});
aea1Hybrid.s4.phases.activate.tag='CIRCUIT A · 45 MIN';
aea1Hybrid.s4.phases.activate.meta=['X1 i X2','2 targetes escollides','Estratègia abans que velocitat'];
